        String majorType = getMajorType(keyType);
        if (!keyTypeToLMKIndex.containsKey(majorType))
            throw new SMException("Unsupported key type: " + majorType);
        index = keyTypeToLMKIndex.get(majorType);
        index |= getVariant(keyType) << 8;
        return index;
    }

