106	            obj, objectName
107	        );
108	        try {
109	            setAttribute (mserver, objectName, "Name", name);
110	            String logger = getAttributeValue (e, "logger");
111	            if (logger != null)
112	                setAttribute (mserver, objectName, "Logger", logger);
113	            String realm = getAttributeValue (e, "realm");
114	            if (realm != null)
115	                setAttribute (mserver, objectName, "Realm", realm);
116	            setAttribute (mserver, objectName, "Server", server);
117	            setAttribute (mserver, objectName, "Persist", e);
