152	    /**
153	     * @param m message to send
154	     * @param timeout amount of time in millis to wait for a response
155	     * @return response or null
156	     */
157	    public ISOMsg request (ISOMsg m, long timeout) throws ISOException {
158	        String key = getKey (m);
159	        String req = key + ".req";
160	        synchronized (isp) {
161	            if (isp.rdp (req) != null)
162	                throw new ISOException ("Duplicate key '" + req + "' detected");
163	            isp.out (req, m);
164	        }
165	        m.setDirection(0);
166	        Chronometer c = new Chronometer();
167	        if (timeout > 0)
168	            sp.out (out, m, timeout);
169	        else
170	            sp.out (out, m);
171	
172	        txCounter.increment();
173	        ISOMsg resp;
174	        try {
175	            synchronized (this) { tx++; rxPending++; }
176	
177	            for (;;) {
178	                resp = (ISOMsg) isp.in (key, timeout);
179	                if (!shouldIgnore (resp))
180	                    break;
181	            }
182	            if (resp == null && isp.inp (req) == null) {
183	                // possible race condition, retry for a few extra seconds
184	                resp = (ISOMsg) isp.in (key, 10000);
185	            }
186	            synchronized (this) {
187	                if (resp != null) {
188	                    rx++;
189	                    lastTxn = System.currentTimeMillis();
190	                } else {
191	                    rxExpired++;
192	                    if (m.getDirection() != ISOMsg.OUTGOING)
193	                        txExpired++;
194	                }
195	            }
196	        } finally {
197	            synchronized (this) { rxPending--; }
198	        }
199	        long elapsed = c.elapsed();
200	        metrics.record("all", elapsed);
201	        if (resp != null) {
202	            responseTimer.record(elapsed, TimeUnit.MILLISECONDS);
203	            metrics.record("ok", elapsed);
204	        }
205	        return resp;
206	    }
207	    public void request (ISOMsg m, long timeout, ISOResponseListener rl, Object handBack)
208	      throws ISOException
209	    {
210	        String key = getKey (m);
211	        String req = key + ".req";
212	        synchronized (isp) {
213	            if (isp.rdp (req) != null)
214	                throw new ISOException ("Duplicate key '" + req + "' detected.");
215	            m.setDirection(0);
216	            AsyncRequest ar = new AsyncRequest (rl, handBack);
217	            synchronized (ar) {
218	                if (timeout > 0)
219	                    ar.setFuture(getScheduledThreadPoolExecutor().schedule(ar, timeout, TimeUnit.MILLISECONDS));
220	            }
221	            isp.out (req, ar, timeout);
222	        }
223	        if (timeout > 0)
224	            sp.out (out, m, timeout);
225	        else
226	            sp.out (out, m);
227	        synchronized (this) { tx++; rxPending++; }
228	    }
