230	    protected boolean isNotifyEligible(ISOMsg msg) {
231	        if (returnRejects)
232	            return true;
233	
234	        try {
235	            return msg.isResponse();
236	        } catch (RuntimeException | ISOException ex) {
237	            // * ArrayIndexOutOfBoundsException - It may occur for messages where
238	            // MTI is not standard 4 characters (eg. FSDISOMsg), then notification is expected.
239	            // * ISOException: When there is no field 0, the error should be logged
240	            return true;
241	        }
242	    }
