 97	            Iterator<LogListener> i = l.listeners.iterator();
 98	            while (i.hasNext() && evt != null) {
 99	                try {
100	                    evt = i.next().log(evt);
101	                } catch (ConcurrentModificationException e) {
102	                    break;
103	                } catch (Throwable t) {
104	                    evt.addMessage (t);
105	                }
